arguments.command:
cd /tmp/sv-8ac16b126891435a8fdc78caedc70d51 && \
# Get more precise symbol names using dynamic symbol table with offsets
# For libmonosgen-2.0.so, use nm -D --defined-only and find the function at each offset
nm -D --defined-only libmonosgen-2.0.so | sort | awk '
BEGIN { 
  split("0x222098 0x222234 0x19bac0 0x19bc14", targets, " ")
  for (i in targets) { t[i] = strtonum(targets[i]) }
}
{ 
  addr = strtonum("0x"$1)
  for (i in t) {
    if (addr <= t[i]) { result[i] = prev_name " + " sprintf("0x%x", t[i] - prev_addr) }
  }
  prev_addr = addr; prev_name = $3
}
END {
  for (i in result) print targets[i], "->", result[i]
}' 2>/dev/null

# Alternative: use objdump to get the function names directly
echo "=== Using objdump disassembly ==="
for addr in 222098 222234 19bac0 19bc14; do
  func=$(aarch64-linux-gnu-objdump -d --start-address=0x$addr --stop-address=0x$(printf '%x' $((0x$addr + 4))) libmonosgen-2.0.so 2>/dev/null | grep '<' | head -1 | sed 's/.*<\(.*\)>.*/\1/' || true)
  if [ -z "$func" ]; then
    func=$(objdump -d --start-address=0x$addr --stop-address=0x$(printf '%x' $((0x$addr + 4))) libmonosgen-2.0.so 2>/dev/null | grep '<' | head -1 | sed 's/.*<\(.*\)>.*/\1/' || true)
  fi
  echo "0x$addr -> $func"
done

